import { useState, useRef } from "react";
import "./URLInput.css";
import socket from "../../socket.js";

// Define text input for links
export default function URLInput() {
	const [url, setUrl] = useState("");
	const buttonRef = useRef("null");
	const [errorText, setErrorText] = useState("");
	const [showError, setShowError] = useState(false);

	// Define function for action upon press
	async function submitSong() {
		// Uncomment the following lines if you want the hammer button to authenticate!
		// Only do this if you know what that means.
		// window.location =
		// 	`https://soundcloud.com/connect` +
		// 	`?client_id=${"RnDqXwDyKyyo41bjlY5hSktjmAOu2D5s"}` +
		// 	`&redirect_uri=https://trackhammer.mit.edu/callback` +
		// 	`&response_type=code`;
		// 	return;
		if (!url.trim()) return;
		socket.emit("addSong", url, (response) => {
			if (response.success) {
				setShowError(false);
				setErrorText("");
			} else if (response.error === undefined) {
				setErrorText("Did not recieve a response from server");
				setShowError(true);
			} else {
				setErrorText(response.error);
				setShowError(true);
			}
		});
		setUrl("");
	}

	// Update the value of the url every time it's changed
	function updateText(e) {
		setUrl(e.target.value);
	}

	function handleKeyDown(e) {
		if (e.key === "Enter") {
			submitSong();
		}
	}

	return (
		<div className="Song-Entry">
			<div className="Text-Input">
				<input
					className="URL-Input"
					name="SoundCloud URL Input"
					placeholder="Enter SoundCloud URL..."
					value={url}
					onChange={updateText}
					onKeyDown={handleKeyDown}
					autoFocus
				/>
				<button
					className="Hammer-Button"
					type="button"
					onClick={submitSong}
					ref={buttonRef}
				>
					HAMMER
				</button>
			</div>
			{/* Conditionally render error messages to the user */}
			<div className={showError ? "Error Visible" : "Error"}>{errorText}</div>
		</div>
	);
}
